import sqlite3
import json
import sys
import requests
from datetime import datetime

def main():
    if len(sys.argv) != 2:
        print("Usage: python status_sync.py < services.txt>", file=sys.stderr)
        sys.exit(1)

    services_file = sys.argv[1]
    services = [line.strip() for line in open(services_file) if line.strip()]

    db = sqlite3.connect('services.db')
    cursor = db.cursor()

    cache = {}

    for service in services:
        cursor.execute("SELECT endpoint, last_sync FROM services WHERE name = ?", (service,))
        row = cursor.fetchone()

        if not row:
            print(f"{service}: missing", file=sys.stderr)
            continue

        endpoint, last_sync = row
        try:
            response = requests.get(f"{endpoint}/status?since={last_sync}")
            data = response.json()
            if not isinstance(data, dict) or 'status' not in data or 'updated_at' not in data:
                print(f"{service}: invalid response", file=sys.stderr)
                continue
            cache[service] = data['updated_at']
        except (requests.RequestException, json.JSONDecodeError):
            print(f"{service}: invalid response", file=sys.stderr)

    db.close()

    try:
        with open('status_cache.json', 'r') as f:
            existing_cache = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        existing_cache = {}

    existing_cache.update(cache)
    print(json.dumps(existing_cache))

if __name__ == "__main__":
    main()

import sqlite3
import sys
import json
import requests
from datetime import datetime

def main():
    services = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            services.append(line)

    cache = {}

    for service in services:
        try:
            conn = sqlite3.connect('services.db')
            cursor = conn.cursor()
            cursor.execute("SELECT endpoint, last_sync FROM services WHERE name = ?", (service,))
            row = cursor.fetchone()
            conn.close()

            if not row:
                print(f"{service}: missing", file=sys.stderr)
                continue

            endpoint, last_sync = row
            try:
                response = requests.get(f"{endpoint}/status?since={last_sync}")
                data = response.json()
                if not isinstance(data, dict) or 'status' not in data or 'updated_at' not in data:
                    print(f"{service}: invalid response", file=sys.stderr)
                    continue
                cache[service] = data['updated_at']
            except (requests.RequestException, json.JSONDecodeError):
                print(f"{service}: invalid response", file=sys.stderr)
        except Exception as e:
            print(f"{service}: database error - {str(e)}", file=sys.stderr)

    if 'status_cache.json' in sys.argv:
        with open('status_cache.json', 'r') as f:
            try:
                existing_cache = json.load(f)
            except json.JSONDecodeError:
                existing_cache = {}
        existing_cache.update(cache)
        with open('status_cache.json', 'w') as f:
            json.dump(existing_cache, f, indent=2)
    else:
        existing_cache = cache

    print(json.dumps(existing_cache, indent=2))

if __name__ == "__main__":
    main()

